#!/usr/bin/env python3
import requests

def check_endpoint(url, name):
    try:
        response = requests.get(url, timeout=10)
        print(f"{name}:")
        print(f"  URL: {url}")
        print(f"  Status Code: {response.status_code}")
        print(f"  Response: {response.text.strip() if response.text else 'No content'}\n")
    except Exception as e:
        print(f"{name}:")
        print(f"  URL: {url}")
        print(f"  Failed to connect: {e}\n")

def main():
    check_endpoint("http://localhost:3003/checkConnectivity?variant=1", "Local Service Check")n    check_endpoint("https://httpstat.us/200", "HTTPStat Check")

if __name__ == "__main__":
    main()

